const logout = () => {
    setAuthToken(null);
    setUser(null);
    // Clear the new-project draft (client name/email/phone) so it can't be
    // read back by whoever logs into this browser next (T-021).
    clearNewProjectDraft();
    api.logout().catch(() => {  — setAuthToken(null) also nulls the module-level `authToken` that api/client.ts's request() reads (`if (authToken) { headers['Authorization'] = `Bearer ${authToken}` }`), so POST /auth/logout arrives with no credentials and backend/app/api/routes/auth.py:751 takes the `if credentials is not None:` branch not at all — revoke_jti() is never called. The revocation it skips is enforced everywhere else (auth.py:709 `if not jti or await is_jti_revoked(jti, db)`, main.py:9257), so the token stays fully valid until its natural expiry, which resolve_session_max_minutes clamps only to [1h, 720h].

@router.get("/oidc/authorize/{provider_id}", response_model=OIDCAuthorizeResponse)
async def oidc_authorize(
    provider_id: int,
    db: AsyncSession = Depends(get_db),
) -> OIDCAuthorizeResponse:  — reachable with no credentials via main.py's PUBLIC_API_PREFIXES entry "/api/v1/auth/oidc/authorize/", and every call runs `async with httpx.AsyncClient(timeout=10) as client: resp = await client.get(discovery_url)` (line 1654, no caching) and then `db.add(AuthEphemeralToken(token=state, token_type=TokenType.OIDC_STATE, ...))` + `await db.commit()` (lines 1692-1702). There is no rate limiter on this route and no global one in main.py — unlike the public tracking route, which carries _track_rate_limited.
